{"rob": "robolang 1.3;

task carry_and_place(robot amr, robot arm, object part, location src, location station, location dst) {
    goal { object_at part dst; }
    plan {
        move amr to src;
        grasp amr part;
        move amr to station;
        place amr part at station;
        move arm to station;
        grasp arm part;
        move arm to dst;
        place arm part at dst;
    }
}
", "task": "carry_and_place", "bindings": [{"param": "amr", "id": "amr1"}, {"param": "arm", "id": "arm_b"}, {"param": "part", "id": "p2"}, {"param": "src", "id": "conveyor_in"}, {"param": "station", "id": "station2"}, {"param": "dst", "id": "bin"}]}
